'use strict';

// MODULES //

var isRowMajor = require( '@stdlib/ndarray/base/assert/is-row-major' );
var cfill = require( '@stdlib/blas/ext/base/cfill' ).ndarray;
var cscal = require( '@stdlib/blas/base/cscal' ).ndarray;
var realf = require( '@stdlib/complex/float32/real' );
var imagf = require( '@stdlib/complex/float32/imag' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );
var reinterpret = require( '@stdlib/strided/base/reinterpret-complex64' );
var muladd = require( '@stdlib/complex/float32/base/mul-add' ).assign;


// FUNCTIONS //

/**
* Tests whether a provided string indicates to transpose a matrix.
*
* @private
* @param {string} str - input string
* @returns {boolean} boolean indicating whether to transpose a matrix
*
* @example
* var bool = isTransposed( 'transpose' );
* // returns true
*
* @example
* var bool = isTransposed( 'conjugate-transpose' );
* // returns true
*
* @example
* var bool = isTransposed( 'no-transpose' );
* // returns false
*/
function isTransposed( str ) { // NOTE: consider moving to a separate helper utility package
	return ( str !== 'no-transpose' );
}


// MAIN //

/**
* Performs one of the matrix-vector operations `y = α*A*x + β*y` or `y = α*A^T*x + β*y`, where `α` and `β` are complex scalars, `x` and `y` are complex vectors, and `A` is an `M` by `N` complex matrix.
*
* @private
* @param {string} trans - specifies whether `A` should be transposed, conjugate-transposed, or not transposed
* @param {NonNegativeInteger} M - number of rows in the matrix `A`
* @param {NonNegativeInteger} N - number of columns in the matrix `A`
* @param {Complex64} alpha - scalar constant
* @param {Complex64Array} A - input matrix
* @param {integer} strideA1 - stride of the first dimension of `A`
* @param {integer} strideA2 - stride of the second dimension of `A`
* @param {NonNegativeInteger} offsetA - starting index for `A`
* @param {Complex64Array} x - first input vector
* @param {integer} strideX - `x` stride length
* @param {NonNegativeInteger} offsetX - starting index for `x`
* @param {Complex64} beta - scalar constant
* @param {Complex64Array} y - second input vector
* @param {integer} strideY - `y` stride length
* @param {NonNegativeInteger} offsetY - starting index for `y`
* @returns {Complex64Array} `y`
*
* @example
* var Complex64Array = require( '@stdlib/array/complex64' );
* var Complex64 = require( '@stdlib/complex/float32/ctor' );
*
* var A = new Complex64Array( [ 1.0, 1.0, 2.0, 2.0, 3.0, 3.0, 4.0, 4.0, 5.0, 5.0, 6.0, 6.0, 7.0, 7.0, 8.0, 8.0 ] );
* var x = new Complex64Array( [ 1.0, 1.0, 2.0, 2.0 ] );
* var y = new Complex64Array( [ 1.0, 1.0, 2.0, 2.0, 3.0, 3.0, 4.0, 4.0 ] );
* var alpha = new Complex64( 0.5, 0.5 );
* var beta = new Complex64( 0.5, -0.5 );
*
* cgemv( 'no-transpose', 4, 2, alpha, A, 1, 4, 0, x, 1, 0, beta, y, 1, 0 );
* // y => <Complex64Array>[ -10.0, 11.0, -12.0, 14.0, -14.0, 17.0, -16.0, 20.0 ]
*/
function cgemv( trans, M, N, alpha, A, strideA1, strideA2, offsetA, x, strideX, offsetX, beta, y, strideY, offsetY ) { // eslint-disable-line max-params, max-len
	var realpha;
	var imalpha;
	var rebeta;
	var imbeta;
	var viewA;
	var viewX;
	var viewY;
	var retmp;
	var imtmp;
	var isrm;
	var xlen;
	var ylen;
	var sign;
	var sa0;
	var sa1;
	var oa2;
	var ix0;
	var ix1;
	var iy0;
	var iy1;
	var rea;
	var ima;
	var rex;
	var imx;
	var oa;
	var ox;
	var oy;
	var sx;
	var sy;
	var i0;
	var i1;
	var ia;

	// layout
	isrm = isRowMajor( [ strideA1, strideA2 ] );

	// lengths
	if ( isTransposed( trans ) ) {
		xlen = M;
		ylen = N;
	} else {
		xlen = N;
		ylen = M;
	}

	// decompose scalars
	rebeta = realf( beta );
	imbeta = imagf( beta );
	realpha = realf( alpha );
	imalpha = imagf( alpha );

	// y = beta*y
	if ( rebeta === 0.0 && imbeta === 0.0 ) {
		cfill( ylen, 0.0, y, strideY, offsetY );
	} else if ( rebeta !== 1.0 || imbeta !== 0.0 ) {
		cscal( ylen, beta, y, strideY, offsetY );
	}

	// if alpha is zero, early return y
	if ( realpha === 0.0 && imalpha === 0.0 ) {
		return y;
	}

	// reinterpret arrays to raw numeric views
	viewA = reinterpret( A, 0 );
	viewX = reinterpret( x, 0 );
	viewY = reinterpret( y, 0 );

	// Set sign to handle conjugation: flip the imaginary part for conjugate-transpose
	if ( trans === 'conjugate-transpose' ) {
		sign = -1;
	} else {
		sign = 1;
	}

	if ( isrm ) {
		// For row-major matrices, the last dimension has the fastest changing index...
		sa0 = strideA2 * 2;                     // offset increment for innermost loop
		sa1 = strideA1 * 2;                     // offset increment for outermost loop
	} else { // isColMajor
		// For column-major matrices, the first dimension has the fastest changing index...
		sa0 = strideA1 * 2;                     // offset increment for innermost loop
		sa1 = strideA2 * 2;                     // offset increment for outermost loop
	}

	// Vector indexing base
	oa = offsetA * 2;
	ox = offsetX * 2;
	oy = offsetY * 2;

	// Vector strides
	sx = strideX * 2;
	sy = strideY * 2;

	// Form: y = α*A*x + y
	if (
		( !isrm && !isTransposed( trans ) ) ||
		( isrm && isTransposed( trans ) )
	) {
		for ( i1 = 0; i1 < xlen; i1++ ) {
			ix1 = ox + ( i1 * sx );
			oa2 = oa + ( i1 * sa1 );
			rex = viewX[ ix1 ];
			imx = viewX[ ix1 + 1 ];
			retmp = f32( ( realpha * rex ) - ( imalpha * imx ) );
			imtmp = f32( ( realpha * imx ) + ( imalpha * rex ) );
			for ( i0 = 0; i0 < ylen; i0++ ) {
				ia = oa2 + ( i0 * sa0 );
				iy0 = oy + ( i0 * sy );
				rea = viewA[ ia ];
				ima = sign * viewA[ ia + 1 ];
				muladd( rea, ima, retmp, imtmp, viewY[ iy0 ], viewY[ iy0 + 1 ], viewY, 1, iy0 ); // eslint-disable-line max-len
			}
		}
		return y;
	}

	// Form: y = α*A^T*x + y
	// ( !isrm && isTransposed( trans ) ) || ( isrm && !isTransposed( trans ) )
	for ( i1 = 0; i1 < ylen; i1++ ) {
		oa2 = oa + ( i1 * sa1 );
		iy1 = oy + ( i1 * sy );
		retmp = 0.0;
		imtmp = 0.0;
		for ( i0 = 0; i0 < xlen; i0++ ) {
			ia = oa2 + ( i0 * sa0 );
			ix0 = ox + ( i0 * sx );
			rea = viewA[ ia ];
			ima = sign * viewA[ ia + 1 ];
			rex = viewX[ ix0 ];
			imx = viewX[ ix0 + 1 ];
			retmp = f32( retmp + f32( ( rea * rex ) - ( ima * imx ) ) );
			imtmp = f32( imtmp + f32( ( rea * imx ) + ( ima * rex ) ) );
		}
		muladd( realpha, imalpha, retmp, imtmp, viewY[ iy1 ], viewY[ iy1 + 1 ], viewY, 1, iy1 ); // eslint-disable-line max-len
	}
	return y;
}


// EXPORTS //

module.exports = cgemv;
